import{_ as a,o as s,c as r,a as o}from"./app.DkoUFz-u.js";const _=JSON.parse('{"title":"数据库层开发-高性能访问-数据分片-分片管理-跨分片查询 学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"data/performance/sharding/management/cross-shard.md","filePath":"data/performance/sharding/management/cross-shard.md"}'),e={name:"data/performance/sharding/management/cross-shard.md"};function n(d,t,i,l,h,p){return s(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="数据库层开发-高性能访问-数据分片-分片管理-跨分片查询-学习笔记" tabindex="-1">数据库层开发-高性能访问-数据分片-分片管理-跨分片查询 学习笔记 <a class="header-anchor" href="#数据库层开发-高性能访问-数据分片-分片管理-跨分片查询-学习笔记" aria-label="Permalink to &quot;数据库层开发-高性能访问-数据分片-分片管理-跨分片查询 学习笔记&quot;">​</a></h1><h2 id="一、概述-什么是跨分片查询" tabindex="-1">一、概述：什么是跨分片查询 <a class="header-anchor" href="#一、概述-什么是跨分片查询" aria-label="Permalink to &quot;一、概述：什么是跨分片查询&quot;">​</a></h2><h3 id="_1-1-定义" tabindex="-1">1.1 定义 <a class="header-anchor" href="#_1-1-定义" aria-label="Permalink to &quot;1.1 定义&quot;">​</a></h3><p><strong>跨分片查询（Cross-Shard Query）</strong> 是指在分库分表架构下，当一条SQL查询涉及的数据分布在多个物理分片（不同数据库实例或不同数据表）时，系统需要从多个分片分别获取数据，再将结果合并后返回的查询过程。</p><h3 id="_1-2-为什么跨分片查询是分库分表后的核心难题" tabindex="-1">1.2 为什么跨分片查询是分库分表后的核心难题 <a class="header-anchor" href="#_1-2-为什么跨分片查询是分库分表后的核心难题" aria-label="Permalink to &quot;1.2 为什么跨分片查询是分库分表后的核心难题&quot;">​</a></h3><p>分库分表通过将数据水平拆分到多个物理节点，解决了单机存储和性能瓶颈。但这种物理隔离也带来了新的问题——原本在单库中可以高效完成的关联查询、聚合查询、排序分页等操作，在分片环境下变得异常复杂。</p><p><strong>核心矛盾</strong>：<strong>数据分片的物理隔离性与业务查询的逻辑完整性之间的矛盾</strong>。</p><p>一旦查询条件中缺少分片键，就不得不将查询<strong>广播到所有分片</strong>，然后聚合结果。当业务需要跨分片聚合分析时，查询路径变得极其复杂，<strong>节点间的网络通信成本甚至超过了计算成本</strong>。</p><p><strong>一个典型场景</strong>：订单表按 <code>user_id</code> 分片，但业务需要按 <code>order_status = &#39;PAID&#39;</code> 查询所有订单——由于查询条件不包含分片键，系统必须扫描所有分片。</p><h2 id="二、跨分片查询的核心挑战" tabindex="-1">二、跨分片查询的核心挑战 <a class="header-anchor" href="#二、跨分片查询的核心挑战" aria-label="Permalink to &quot;二、跨分片查询的核心挑战&quot;">​</a></h2><h3 id="_2-1-数据分散导致的索引失效" tabindex="-1">2.1 数据分散导致的索引失效 <a class="header-anchor" href="#_2-1-数据分散导致的索引失效" aria-label="Permalink to &quot;2.1 数据分散导致的索引失效&quot;">​</a></h3><p>分布式环境中，数据被水平切分到多个节点，每个节点维护的是<strong>局部索引</strong>，而非全局索引。全局查询需要聚合多节点结果，这对索引结构提出了跨节点协同的要求。</p><h3 id="_2-2-join操作的复杂性" tabindex="-1">2.2 JOIN操作的复杂性 <a class="header-anchor" href="#_2-2-join操作的复杂性" aria-label="Permalink to &quot;2.2 JOIN操作的复杂性&quot;">​</a></h3><p>分库分表后，原本单库中的JOIN操作面临多重困难：</p><ul><li><strong>分片键不一致</strong>：两张表使用不同的分片键，数据分布在不同节点，无法在单分片内完成JOIN</li><li><strong>笛卡尔积爆炸</strong>：非绑定表关联时，路由会产生大量笛卡尔积组合</li><li><strong>数据拉取成本</strong>：需要将各分片数据拉到中间件内存中处理，网络和内存开销巨大</li></ul><h3 id="_2-3-聚合与排序的全局性问题" tabindex="-1">2.3 聚合与排序的全局性问题 <a class="header-anchor" href="#_2-3-聚合与排序的全局性问题" aria-label="Permalink to &quot;2.3 聚合与排序的全局性问题&quot;">​</a></h3><p>跨分片的聚合查询（如 <code>COUNT(*)</code>、<code>SUM(amount)</code>）需要每个节点先计算本地结果，再将中间结果传回协调节点进行二次聚合。排序和分页更为棘手——每个分片只能返回局部排序结果，需要在协调节点进行<strong>全局重排序</strong>。</p><h3 id="_2-4-分布式事务与一致性" tabindex="-1">2.4 分布式事务与一致性 <a class="header-anchor" href="#_2-4-分布式事务与一致性" aria-label="Permalink to &quot;2.4 分布式事务与一致性&quot;">​</a></h3><p>跨分片操作往往涉及分布式事务，协调开销在跨节点网络延迟下会显著拖慢速度。跨分片更新需要协调两阶段提交（2PC），<strong>锁持有时间随分片数量线性增加</strong>。</p><h3 id="_2-5-分片键选择的局限性" tabindex="-1">2.5 分片键选择的局限性 <a class="header-anchor" href="#_2-5-分片键选择的局限性" aria-label="Permalink to &quot;2.5 分片键选择的局限性&quot;">​</a></h3><p><strong>一张表只能选择一个分片键</strong>——选了 <code>user_id</code>，用户维度的本地JOIN问题解决了，但商家维度的查询依然要跨分片。真正的问题不是&quot;如何根治跨分片JOIN&quot;，而是&quot;如何为最重要的查询路径做出最优的分布决策，同时接受其他路径的代价&quot;。</p><h2 id="三、跨分片查询的解决思路概览" tabindex="-1">三、跨分片查询的解决思路概览 <a class="header-anchor" href="#三、跨分片查询的解决思路概览" aria-label="Permalink to &quot;三、跨分片查询的解决思路概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>解决思路</th><th>核心思想</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>绑定表（ER分片）</strong></td><td>有关联关系的表使用相同分片键，放在同一分片</td><td>主子表关联查询</td></tr><tr><td><strong>广播表（全局表）</strong></td><td>小表在每个分片全量冗余</td><td>字典表、配置表关联</td></tr><tr><td><strong>全局索引</strong></td><td>为分片键之外的字段建立映射索引</td><td>非分片键查询</td></tr><tr><td><strong>联邦查询</strong></td><td>中间件层实现分布式SQL执行引擎</td><td>复杂跨分片查询</td></tr><tr><td><strong>ES宽表</strong></td><td>将数据实时同步到搜索引擎</td><td>复杂多维查询、全文检索</td></tr><tr><td><strong>应用层组装</strong></td><td>多次查询+内存计算</td><td>灵活但开发成本高</td></tr></tbody></table><h2 id="四、核心概念与关键技术" tabindex="-1">四、核心概念与关键技术 <a class="header-anchor" href="#四、核心概念与关键技术" aria-label="Permalink to &quot;四、核心概念与关键技术&quot;">​</a></h2><h3 id="_4-1-绑定表-binding-table-er表" tabindex="-1">4.1 绑定表（Binding Table / ER表） <a class="header-anchor" href="#_4-1-绑定表-binding-table-er表" aria-label="Permalink to &quot;4.1 绑定表（Binding Table / ER表）&quot;">​</a></h3><p><strong>定义</strong>：指分片规则一致的一组分片表。例如，<code>t_order</code> 表和 <code>t_order_item</code> 表均按照 <code>order_id</code> 分片，则这两张表互为绑定表关系。</p><p><strong>核心要求</strong>：使用绑定表进行多表关联查询时，<strong>必须使用分片键进行关联</strong>，否则会出现笛卡尔积关联或跨库关联。</p><p><strong>效果对比</strong>：</p><p>假设SQL为：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_140thh"> i.</span><span class="__shiki_1itgoe">*</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> t_order o </span><span class="__shiki_1itgoe">JOIN</span><span class="__shiki_140thh"> t_order_item i </span></span>
<span class="line"><span class="__shiki_1itgoe">ON</span><span class="__shiki_dzsirb"> o</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">order_id</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_dzsirb"> i</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">order_id</span><span class="__shiki_1itgoe"> WHERE</span><span class="__shiki_dzsirb"> o</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">order_id</span><span class="__shiki_1itgoe"> IN</span><span class="__shiki_140thh"> (</span><span class="__shiki_dzsirb">10</span><span class="__shiki_140thh">, </span><span class="__shiki_dzsirb">11</span><span class="__shiki_140thh">);</span></span></code></pre></div><ul><li><p><strong>不配置绑定表</strong>：order_id=10路由至第0片，order_id=11路由至第1片，产生4条SQL的笛卡尔积：</p><ul><li><code>t_order_0</code> JOIN <code>t_order_item_0</code></li><li><code>t_order_0</code> JOIN <code>t_order_item_1</code></li><li><code>t_order_1</code> JOIN <code>t_order_item_0</code></li><li><code>t_order_1</code> JOIN <code>t_order_item_1</code></li></ul></li><li><p><strong>配置绑定表后</strong>：路由SQL缩减为2条：</p><ul><li><code>t_order_0</code> JOIN <code>t_order_item_0</code></li><li><code>t_order_1</code> JOIN <code>t_order_item_1</code></li></ul></li></ul><p>绑定表的核心价值在于<strong>消除笛卡尔积</strong>，大幅提升关联查询效率。</p><p>在MyCat中，对应概念为<strong>ER表</strong>——子表的存储位置依赖于父表，在物理上紧邻存放。配置方式是在 <code>schema.xml</code> 的 <code>table</code> 节点下增加 <code>childTable</code> 子节点。</p><h3 id="_4-2-广播表-broadcast-table-全局表" tabindex="-1">4.2 广播表（Broadcast Table / 全局表） <a class="header-anchor" href="#_4-2-广播表-broadcast-table-全局表" aria-label="Permalink to &quot;4.2 广播表（Broadcast Table / 全局表）&quot;">​</a></h3><p><strong>定义</strong>：指所有的分片数据源中都存在的表，表结构和数据在每个数据库中均完全一致。</p><p><strong>适用场景</strong>：数据量不大且需要与海量数据的表进行关联查询的场景，例如字典表、配置表、地区表等。</p><p><strong>工作原理</strong>：广播表在每个分片库中都有全量数据副本，分片表与广播表关联查询时，变成纯粹的<strong>本地JOIN</strong>，速度极快。插入、更新和删除操作会实时在每一个分片中执行。</p><p>在Vitess中，对应的概念为<strong>Reference Table（参考表）</strong> ——将分片keyspace中的表标记为参考表后，系统会将其视为在所有分片中具有相同数据行集。与分片表JOIN时，查询在每个分片内本地执行。</p><h3 id="_4-3-全局索引-global-index" tabindex="-1">4.3 全局索引（Global Index） <a class="header-anchor" href="#_4-3-全局索引-global-index" aria-label="Permalink to &quot;4.3 全局索引（Global Index）&quot;">​</a></h3><p><strong>定义</strong>：跨多个数据节点维护的统一索引结构，其核心特征在于<strong>索引元数据与数据分片的解耦</strong>。</p><p><strong>解决什么问题</strong>：当查询条件不包含分片键时，无法直接路由到目标分片，只能广播到所有分片。全局索引为这类查询提供了一条<strong>二次路由</strong>的路径。</p><p><strong>实现方式</strong>：创建一个全局索引表，记录非分片键到分片位置的映射。例如为 <code>user_id</code> 创建全局索引表，记录每笔订单所在的分片位置：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">CREATE</span><span class="__shiki_1itgoe"> TABLE</span><span class="__shiki_1t8gfj"> global_index</span><span class="__shiki_140thh"> (</span></span>
<span class="line"><span class="__shiki_140thh">    user_id </span><span class="__shiki_1itgoe">BIGINT</span><span class="__shiki_1itgoe"> NOT NULL</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_140thh">    shard_key </span><span class="__shiki_1itgoe">VARCHAR</span><span class="__shiki_140thh">(</span><span class="__shiki_dzsirb">32</span><span class="__shiki_140thh">) </span><span class="__shiki_1itgoe">NOT NULL</span><span class="__shiki_140thh">,  </span><span class="__shiki_21nrsd">-- 标识分片位置</span></span>
<span class="line"><span class="__shiki_1itgoe">    PRIMARY KEY</span><span class="__shiki_140thh"> (user_id)</span></span>
<span class="line"><span class="__shiki_140thh">);</span></span></code></pre></div><p>查询时先查全局索引定位分片，再路由到具体分片执行查询。</p><h3 id="_4-4-联邦查询-sql-federation" tabindex="-1">4.4 联邦查询（SQL Federation） <a class="header-anchor" href="#_4-4-联邦查询-sql-federation" aria-label="Permalink to &quot;4.4 联邦查询（SQL Federation）&quot;">​</a></h3><p><strong>定义</strong>：ShardingSphere提供的跨数据库实例分布式查询能力，将业务端原有的查询转换为分布式查询，并在分布式查询场景下进行相应的SQL优化。</p><p><strong>适用场景</strong>：跨数据库关联查询、子查询、分页、排序、聚合查询等。</p><p><strong>核心组件</strong>：</p><ol><li><strong>SQL联邦决策器（SQLFederationDecider）</strong> ：判断是否启用SQL联邦执行模式，决策条件包括查询涉及多个数据库实例、包含跨分片表的JOIN操作、复杂的子查询或聚合操作等</li><li><strong>SQL联邦引擎（SQLFederationEngine）</strong> ：联邦查询的核心执行组件</li><li><strong>优化器上下文（OptimizerContext）</strong> ：管理数据库元数据和优化器配置</li></ol><p><strong>技术架构</strong>：基于Apache Calcite框架构建，采用查询重写和优化器技术。内部使用<strong>关系代数优化查询计划</strong>，通过最优计划查询出结果。</p><p><strong>⚠️ 注意</strong>：联邦查询功能目前仍处于<strong>实验/开发阶段</strong>，暂不适合核心系统生产环境使用。</p><h3 id="_4-5-字段冗余" tabindex="-1">4.5 字段冗余 <a class="header-anchor" href="#_4-5-字段冗余" aria-label="Permalink to &quot;4.5 字段冗余&quot;">​</a></h3><p>通过在表中冗余存储关联表的字段，将<strong>JOIN操作转化为单表查询</strong>。例如订单表中冗余存储用户名称、商品名称等字段，避免关联查询。</p><p><strong>优点</strong>：查询效率极高，无需跨表 <strong>缺点</strong>：数据冗余带来一致性问题，更新时需要同步维护</p><h2 id="五、主流中间件的跨分片查询实现" tabindex="-1">五、主流中间件的跨分片查询实现 <a class="header-anchor" href="#五、主流中间件的跨分片查询实现" aria-label="Permalink to &quot;五、主流中间件的跨分片查询实现&quot;">​</a></h2><h3 id="_5-1-apache-shardingsphere" tabindex="-1">5.1 Apache ShardingSphere <a class="header-anchor" href="#_5-1-apache-shardingsphere" aria-label="Permalink to &quot;5.1 Apache ShardingSphere&quot;">​</a></h3><p>ShardingSphere采用<strong>两套执行引擎</strong>处理跨分片查询：</p><h4 id="standard内核流程" tabindex="-1">Standard内核流程 <a class="header-anchor" href="#standard内核流程" aria-label="Permalink to &quot;Standard内核流程&quot;">​</a></h4><p>适用于标准分片场景：<strong>SQL解析 → SQL路由 → SQL改写 → SQL执行 → 结果归并</strong>。</p><h4 id="federation执行引擎流程" tabindex="-1">Federation执行引擎流程 <a class="header-anchor" href="#federation执行引擎流程" aria-label="Permalink to &quot;Federation执行引擎流程&quot;">​</a></h4><p>适用于复杂跨分片查询：<strong>SQL解析 → 逻辑优化 → 物理优化 → 优化执行</strong>（依赖Standard内核流程）。</p><p><strong>跨分片查询的三种路由模式</strong>：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>性能</th></tr></thead><tbody><tr><td>绑定表关联</td><td>分片键一致，路由到同一分片</td><td>最优</td></tr><tr><td>广播表关联</td><td>小表全量冗余，本地JOIN</td><td>优</td></tr><tr><td>联邦查询</td><td>跨实例分布式执行</td><td>一般（实验阶段）</td></tr></tbody></table><h3 id="_5-2-mycat" tabindex="-1">5.2 MyCat <a class="header-anchor" href="#_5-2-mycat" aria-label="Permalink to &quot;5.2 MyCat&quot;">​</a></h3><p>MyCat支持多种跨分片JOIN方式：</p><table tabindex="0"><thead><tr><th>方式</th><th>原理</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>ER表</strong></td><td>父子表相同分片键，数据同片存储</td><td>主子表关联</td></tr><tr><td><strong>全局表</strong></td><td>小表全量冗余</td><td>字典表关联</td></tr><tr><td><strong>ShareJoin</strong></td><td>小表全量拉取+大表分片查询+内存Hash Join</td><td>两表JOIN</td></tr><tr><td><strong>Catlet（人工智能）</strong></td><td>通过编程方式解决特定跨分片JOIN逻辑</td><td>复杂业务JOIN</td></tr></tbody></table><p><strong>ShareJoin执行流程</strong>（以订单表JOIN用户表为例）：</p><ol><li>小表（users）全量数据拉取到MyCAT</li><li>构建 <code>user_id</code> 哈希表</li><li>向orders各分片发送带 <code>user_id</code> 过滤的查询</li><li>在MyCAT内存中完成Hash Join，返回结果</li></ol><p><strong>Catlet机制</strong>：MyCAT提供特定的API供程序员编程解决业务系统中特定的跨分片SQL的JOIN逻辑。</p><h3 id="_5-3-vitess" tabindex="-1">5.3 Vitess <a class="header-anchor" href="#_5-3-vitess" aria-label="Permalink to &quot;5.3 Vitess&quot;">​</a></h3><p>Vitess通过<strong>VSchema（虚拟Schema）</strong> 管理分片路由和查询优化：</p><p><strong>Reference Table</strong>：将小表标记为参考表，在所有分片中保持相同数据，JOIN时本地执行。</p><p><strong>Lookup Vindex（查找索引）</strong> ：Vitess支持跨分片索引的概念，可以创建和管理查找索引来实现非分片键的快速路由。</p><p><strong>查询改写</strong>：复杂跨分片JOIN查询可能需要先从保持vindex查找表的tablet获取信息，然后使用这些信息查询两个不同分片获取更多数据，最后将结果合并返回。</p><p><strong>聚合下推</strong>：当按至少一个分片键进行分组时，Vitess将聚合下推到MySQL，然后在协调层聚合每个分片的结果——各分片并行处理不同数据块，查询速度快。</p><h2 id="六、结果归并-result-merger" tabindex="-1">六、结果归并（Result Merger） <a class="header-anchor" href="#六、结果归并-result-merger" aria-label="Permalink to &quot;六、结果归并（Result Merger）&quot;">​</a></h2><p>跨分片查询的<strong>最后一步</strong>是将多个分片的执行结果归并，通过统一的JDBC接口输出。</p><h3 id="_6-1-功能分类" tabindex="-1">6.1 功能分类 <a class="header-anchor" href="#_6-1-功能分类" aria-label="Permalink to &quot;6.1 功能分类&quot;">​</a></h3><p>ShardingSphere支持的结果归并从功能上分为5种类型：</p><ul><li><strong>遍历</strong>：简单的结果集遍历</li><li><strong>排序</strong>：全局排序</li><li><strong>分组</strong>：GROUP BY聚合</li><li><strong>分页</strong>：跨分片分页</li><li><strong>聚合</strong>：SUM、COUNT、AVG等</li></ul><h3 id="_6-2-结构分类" tabindex="-1">6.2 结构分类 <a class="header-anchor" href="#_6-2-结构分类" aria-label="Permalink to &quot;6.2 结构分类&quot;">​</a></h3><p>从结构划分，可分为三种：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>流式归并</strong></td><td>边获取边返回，内存占用小</td><td>简单查询、排序</td></tr><tr><td><strong>内存归并</strong></td><td>全部加载到内存后再处理</td><td>分组、聚合</td></tr><tr><td><strong>装饰者归并</strong></td><td>在现有归并基础上追加功能</td><td>分页等增强场景</td></tr></tbody></table><h3 id="_6-3-跨分片分页的挑战" tabindex="-1">6.3 跨分片分页的挑战 <a class="header-anchor" href="#_6-3-跨分片分页的挑战" aria-label="Permalink to &quot;6.3 跨分片分页的挑战&quot;">​</a></h3><p>分库分表下的分页查询是<strong>经典难题</strong>。</p><p><strong>问题</strong>：用户请求&quot;按创建时间倒序显示第11-20条订单&quot;，系统需从<strong>所有分片</strong>中获取排序后的数据片段，再在协调节点进行二次排序和截取。</p><p><strong>方案对比</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>原理</th><th>优缺点</th></tr></thead><tbody><tr><td><strong>偏移量放大</strong></td><td>各分片查询 <code>LIMIT offset + N</code>，归并再取N</td><td>简单，但深分页性能差</td></tr><tr><td><strong>游标分页</strong></td><td>使用 <code>WHERE id &gt; last_id LIMIT N</code></td><td>性能好，但不支持跳页</td></tr><tr><td><strong>搜索引擎</strong></td><td>数据同步到ES，查询走ES</td><td>完全屏蔽复杂度，但引入额外组件</td></tr></tbody></table><h2 id="七、跨分片查询的优化策略" tabindex="-1">七、跨分片查询的优化策略 <a class="header-anchor" href="#七、跨分片查询的优化策略" aria-label="Permalink to &quot;七、跨分片查询的优化策略&quot;">​</a></h2><h3 id="_7-1-设计层面优化" tabindex="-1">7.1 设计层面优化 <a class="header-anchor" href="#_7-1-设计层面优化" aria-label="Permalink to &quot;7.1 设计层面优化&quot;">​</a></h3><p><strong>（1）合理选择分片键</strong> 分片键的选择应满足三个标准：</p><ul><li><strong>高区分度</strong>：数据在所有分片间均匀分布</li><li><strong>查询亲和性</strong>：绝大多数查询条件中都能携带分片键</li><li><strong>业务稳定性</strong>：分片键值不会频繁变更</li></ul><p>在订单系统中，<strong>用户ID比订单ID更适合作为分片键</strong>，因为用户的订单查询远多于单笔订单的详情查询。</p><p><strong>（2）使用绑定表</strong> 将有关联关系的表使用<strong>相同的分片键和分片算法</strong>，确保关联数据落在同一分片。</p><p><strong>（3）使用广播表</strong> 将字典表、配置表等小表设为广播表，消除跨分片关联。</p><p><strong>（4）字段冗余</strong> 将高频关联字段冗余到主表中，将JOIN转化为单表查询。</p><h3 id="_7-2-查询层面优化" tabindex="-1">7.2 查询层面优化 <a class="header-anchor" href="#_7-2-查询层面优化" aria-label="Permalink to &quot;7.2 查询层面优化&quot;">​</a></h3><ul><li><strong>JOIN条件优先使用分片键等值连接</strong></li><li><strong>用结果集小的表作为驱动表</strong>，减少JOIN循环次数</li><li><strong>避免深分页</strong>，使用游标或搜索引擎替代</li><li><strong>避免在分片键上使用函数</strong>，否则会导致路由失效</li></ul><h3 id="_7-3-架构层面优化" tabindex="-1">7.3 架构层面优化 <a class="header-anchor" href="#_7-3-架构层面优化" aria-label="Permalink to &quot;7.3 架构层面优化&quot;">​</a></h3><p><strong>（1）全局二级索引</strong> 为分片键之外的查询字段建立全局索引，实现二次路由。</p><p><strong>（2）ES宽表方案</strong> 利用CDC工具实时捕获分库分表中的数据变更，同步到Elasticsearch构建实时宽表。所有复杂查询直接走搜索引擎，完全屏蔽分库分表的复杂性。</p><p><strong>（3）读写分离</strong> 将聚合查询等复杂操作引导至只读副本，减轻主库压力。</p><h3 id="_7-4-优化策略总结" tabindex="-1">7.4 优化策略总结 <a class="header-anchor" href="#_7-4-优化策略总结" aria-label="Permalink to &quot;7.4 优化策略总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优化策略</th><th>实施成本</th><th>效果</th><th>适用场景</th></tr></thead><tbody><tr><td>合理选择分片键</td><td>低（设计阶段）</td><td>高</td><td>所有场景</td></tr><tr><td>绑定表/ER表</td><td>中</td><td>高</td><td>主子表关联</td></tr><tr><td>广播表/全局表</td><td>低</td><td>高</td><td>字典表关联</td></tr><tr><td>字段冗余</td><td>中</td><td>高</td><td>高频关联字段</td></tr><tr><td>全局索引</td><td>高</td><td>中</td><td>非分片键查询</td></tr><tr><td>ES宽表</td><td>高</td><td>高</td><td>复杂多维查询</td></tr><tr><td>联邦查询</td><td>低（配置开启）</td><td>中</td><td>实验性场景</td></tr></tbody></table><h2 id="八、最佳实践总结" tabindex="-1">八、最佳实践总结 <a class="header-anchor" href="#八、最佳实践总结" aria-label="Permalink to &quot;八、最佳实践总结&quot;">​</a></h2><h3 id="_8-1-设计阶段的三条核心原则" tabindex="-1">8.1 设计阶段的三条核心原则 <a class="header-anchor" href="#_8-1-设计阶段的三条核心原则" aria-label="Permalink to &quot;8.1 设计阶段的三条核心原则&quot;">​</a></h3><ol><li><strong>分片键即生命线</strong>：分片键的选择是分库分表设计中最关键的单点决策，一旦选定就很难更改</li><li><strong>关联表同分片</strong>：有JOIN关系的表尽量使用相同的分片键，确保数据&quot;共处一室&quot;</li><li><strong>小表全量冗余</strong>：字典表、配置表等使用广播表，避免跨分片关联</li></ol><h3 id="_8-2-跨分片查询的四级应对策略" tabindex="-1">8.2 跨分片查询的四级应对策略 <a class="header-anchor" href="#_8-2-跨分片查询的四级应对策略" aria-label="Permalink to &quot;8.2 跨分片查询的四级应对策略&quot;">​</a></h3><p><strong>第一级（最优）</strong> ：避免跨分片查询</p><ul><li>合理设计分片键，让绝大多数查询命中单分片</li><li>使用绑定表、广播表</li></ul><p><strong>第二级</strong>：中间件层优化</p><ul><li>利用绑定表消除笛卡尔积</li><li>利用广播表实现本地JOIN</li></ul><p><strong>第三级</strong>：应用层处理</p><ul><li>多次查询+内存组装</li><li>字段冗余</li></ul><p><strong>第四级（兜底）</strong> ：引入外部系统</p><ul><li>ES宽表</li><li>数据仓库</li></ul><h3 id="_8-3-核心启示" tabindex="-1">8.3 核心启示 <a class="header-anchor" href="#_8-3-核心启示" aria-label="Permalink to &quot;8.3 核心启示&quot;">​</a></h3><p>跨分片查询是分库分表架构中<strong>无法完全消除</strong>的代价。架构师的目标不是&quot;消灭跨分片查询&quot;，而是：</p><blockquote><p><strong>&quot;为最重要的查询路径做出最优的分布决策，同时接受其他路径的代价。&quot;</strong></p></blockquote><p>通过合理的分片键选择、绑定表配置、广播表使用和查询优化，可以将跨分片查询的影响控制在可接受范围内。对于无法避免的复杂跨分片查询，ES宽表、全局索引等架构手段提供了有效的补充方案。</p><h2 id="九、总结" tabindex="-1">九、总结 <a class="header-anchor" href="#九、总结" aria-label="Permalink to &quot;九、总结&quot;">​</a></h2><p>跨分片查询是分库分表架构中最复杂、影响最深远的问题之一。理解跨分片查询需要把握以下要点：</p><ol><li><strong>本质矛盾</strong>：数据分片的物理隔离性与业务查询的逻辑完整性之间的矛盾</li><li><strong>核心挑战</strong>：索引失效、JOIN复杂、聚合困难、分布式事务、分片键局限</li><li><strong>关键技术</strong>：绑定表（消除笛卡尔积）、广播表（本地JOIN）、全局索引（二次路由）、联邦查询（分布式执行）</li><li><strong>主流实现</strong>：ShardingSphere（Standard+Federation双引擎）、MyCat（ER表+ShareJoin+Catlet）、Vitess（Reference Table+Lookup Vindex）</li><li><strong>结果归并</strong>：流式归并、内存归并、装饰者归并，支持遍历、排序、分组、分页、聚合</li><li><strong>优化策略</strong>：合理选分片键→绑定表/广播表→字段冗余→全局索引→ES宽表，层层递进</li><li><strong>核心原则</strong>：分片键选择是单点决策，关联表应同分片，小表应全量冗余</li></ol>`,123)])])}const c=a(e,[["render",n]]);export{_ as __pageData,c as default};
